import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------
# CUDA kernel for GEMM: C = A^T @ B^T  (A shape (K, M), B shape (N, K))
# Each thread computes one output element C[i, j] = sum_k A[k, i] * B[j, k]
# -------------------------------------------------------------------------
gemm_kernel_source = """
__global__ void gemm_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Each thread computes one output element: row i (0..M-1), col j (0..N-1)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N;   // row index
        int j = idx % N;   // column index
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is stored as [K][M] -> flat index: k * M + i
            int a_idx = k * M + i;
            // B is stored as [N][K] -> flat index: j * K + k
            int b_idx = j * K + k;
            sum += A[a_idx] * B[b_idx];
        }
        C[idx] = sum;
    }
}
"""

# -------------------------------------------------------------------------
# Custom CUDA function for matrix multiplication (C = A^T @ B^T)
# -------------------------------------------------------------------------
matmul_cuda_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A: shape (K, M), B: shape (N, K)
    int M = A.size(1);   // columns of A -> rows of output
    int K = A.size(0);
    int N = B.size(0);

    float* A_ptr = A.data_ptr<float>();
    float* B_ptr = B.data_ptr<float>();
    float* C_ptr = torch::empty(M * N, device(A.device));

    const int block_size = 256;
    const int num_blocks = (M * N + block_size - 1) / block_size;

    gemm_kernel<<<num_blocks, block_size>>>(
        A_ptr,
        B_ptr,
        C_ptr,
        M,
        K,
        N
    );

    // Return a contiguous tensor on the same device.
    return torch::from_blob(C_ptr, {M, N}).contiguous().cuda()
}
"""

# Load the custom matmul operator via load_inline
matmul = load_inline(
    name="matmul",
    cpp_sources="torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);",
    cuda_sources=gemm_kernel_source + "\n" + matmul_cuda_source,
    functions=["matmul_cuda"],
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.matmul = matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication C = A^T @ B^T.

        Args:
            A: Input tensor of shape (K, M).
            B: Input tensor of shape (N, K).

        Returns:
            Output tensor of shape (M, N).
        """
        return self.matmul(A, B)
